using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class HospitalFrontAudit{static HospitalFrontAudit(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("HospitalFrontAudit.request"))return;File.Delete("HospitalFrontAudit.request");try{var sc=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var f=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>()).Single(g=>g.name=="Building_06_01_Material #26_0");var lines=new List<string>();foreach(var mf in f.GetComponentsInChildren<MeshFilter>()){var m=mf.sharedMesh;var p=m.vertices.Select(mf.transform.TransformPoint).ToArray();var uv=m.uv;var ids=m.triangles;lines.Add(mf.name+" "+AssetDatabase.GetAssetPath(m)+" vertices="+m.vertexCount);for(int k=0;k<ids.Length;k+=3){var a=p[ids[k]];var b=p[ids[k+1]];var c=p[ids[k+2]];var n=Vector3.Cross(b-a,c-a).normalized;var mid=(a+b+c)/3;if(mid.x<-140||Mathf.Abs(n.x)<.65f)continue;float err=0;foreach(int i in new[]{ids[k],ids[k+1],ids[k+2]}){float vv=p[i].y<=45.7f?Mathf.Lerp(.026f,.691f,Mathf.InverseLerp(27.6664f,45.7f,p[i].y)):Mathf.Lerp(.691f,.990f,Mathf.InverseLerp(45.7f,59.47861f,p[i].y));err=Mathf.Max(err,Mathf.Abs(uv[i].y-vv));}lines.Add(k/3+" center="+mid+" nx="+n.x+" Y="+Mathf.Min(a.y,b.y,c.y)+".."+Mathf.Max(a.y,b.y,c.y)+" uv="+uv[ids[k]]+" / "+uv[ids[k+1]]+" / "+uv[ids[k+2]]+" mapError="+err);}}File.WriteAllLines("FinalEnvironmentRoadReview/HospitalFrontAudit.txt",lines);}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/HospitalFrontAudit.txt",e.ToString());}}}